/*************************************************
 * Name:        encode_h
 *
 * Description: rANS encode polynomial vector h
 *
 * Arguments:   - uint8_t *buf: pointer to output buffer
 *              - const int32_t *h: pointer to polynomial vector h
 * 
 * Returns:     0 on success, 1 on failure
 **************************************************/
uint16_t encode_h(uint8_t *buf, const int32_t *h) {
    size_t size_encoded;
    RansState rans;
    uint8_t *ptr;
    size_t size_h = N * K;
    int32_t tmp;
    uint8_t s;
    uint8_t encoding[size_h]; // 上界 buffer

    RansEncInit(&rans);
    ptr = encoding + size_h; // rANS 反向写

    for (size_t i = size_h; i > 0; i--) {
        tmp = h[i-1];

        /* -------- 映射到 symbol -------- */
        if (tmp >= -OFFSET_H_CENTER && tmp <= OFFSET_H_CENTER) {
            s = (uint8_t)(tmp + OFFSET_H_CENTER);
        } else if (tmp >= -OFFSET_H_NEG && tmp < -OFFSET_H_NEG + OFFSET_H_EDGE) {
            s = (uint8_t)(tmp + OFFSET_H_NEG + OFFSET_H_NEG_START);
        } else if (tmp >= OFFSET_H_POS && tmp < OFFSET_H_POS + OFFSET_H_EDGE) {
            s = (uint8_t)(tmp - OFFSET_H_POS + OFFSET_H_POS_START);
        } else {
            return 0; // 编码失败 - 值超出范围
        }

        /* -------- rANS 编码 -------- */
        RansEncPutSymbol(&rans, &ptr, &esyms_h[s]);

        // 至少保留 4 字节给 flush
        if (ptr < encoding + 4) {
            return 0;
        }
    }

    RansEncFlush(&rans, &ptr);

    size_encoded = encoding + size_h - ptr;
    memcpy(buf, ptr, size_encoded);
    return size_encoded;
}

/*************************************************
 * Name:        decode_h
 *
 * Description: rANS decode polynomial vector h with extended mapping
 *
 * Arguments:   - int32_t *h: pointer to output polynomial vector
 *              - const uint8_t *buf: pointer to encoded buffer
 *              - uint16_t size_in: length of encoded buffer
 *
 * Returns:     0 on success, 1 on failure
 *************************************************/
uint16_t decode_h(int32_t *h, const uint8_t *buf, uint16_t size_in) {
    size_t size_used;
    RansState rans;
    size_t size_h = N * K;
    int32_t tmp;
    uint8_t s;
    const uint8_t *buf_start = buf;
    const uint8_t *buf_end = buf + size_in;

    if (RansDecInit(&rans, (uint8_t **) &buf)) {
        return 1; // corrupted initial state
    }

    for (size_t i = 0; i < size_h; i++) {
        s = symbol_h[RansDecGet(&rans, SCALE_BITS)];

        if (s >= M_H) {
            return 1; // invalid symbol
        }

        if (s <= OFFSET_H_CENTER * 2) {
            tmp = s - OFFSET_H_CENTER;
        } else if (s < OFFSET_H_NEG_START + OFFSET_H_EDGE) {
            tmp = s - OFFSET_H_NEG_START - OFFSET_H_NEG;
        } else {
            tmp = s - OFFSET_H_POS_START + OFFSET_H_POS;
        }

        h[i] = tmp;
        RansDecAdvanceSymbol(&rans, (uint8_t **) &buf, buf_end, &dsyms_h[s], SCALE_BITS);
    }

    if (RansDecVerify(&rans)) {
        return 1; // corrupted final state
    }

    size_used = buf - buf_start;
    if (size_used != size_in) {
        return 1; // size mismatch
    }

    return 0;
}

/*************************************************
 * Name:        encode_hb_z1
 *
 * Description: rANS encode polynomial vector HighBits(z1)
 *
 * Arguments:   - uint8_t *buf: pointer to output buffer
 *              - const int32_t *hb_z1: pointer to polynomial vector
 *HighBits(z1)
 **************************************************/
uint16_t encode_hb_z1(uint8_t *buf, const int32_t *hb_z1) {
    size_t size_encoded;
    RansState rans;
    uint8_t *ptr;
    size_t size_hb_z1 = N * L;
    uint8_t s;
    int32_t tmp;
    uint8_t encoding[size_hb_z1]; 

    RansEncInit(&rans);
    ptr = encoding + size_hb_z1; 

    for (size_t i = size_hb_z1; i > 0; i--) {
        tmp = hb_z1[i-1];

        /* -------- 合法性检查 & 映射到 symbol -------- */
        if (tmp >= 0 && tmp < OFFSET_HB_Z1_POS_START) {
            s = (uint8_t)tmp;
        } else if (tmp >= OFFSET_HB_Z1_POS && tmp < OFFSET_HB_Z1_POS + OFFSET_HB_Z1_POS_START - 1) {
            s = (uint8_t)(tmp - OFFSET_HB_Z1_POS + OFFSET_HB_Z1_POS_START); // tmp - 1011
        } else {
            return 0; // 编码失败
        }

        /* -------- rANS 编码 -------- */
        RansEncPutSymbol(&rans, &ptr, &esyms_hb_z1[s]);

        // 至少保留 4 字节给 flush
        if (ptr < encoding + 4) {
            return 0;
        }
    }

    RansEncFlush(&rans, &ptr);

    size_encoded = encoding + size_hb_z1 - ptr;
    memcpy(buf, ptr, size_encoded);
    return size_encoded;
}

/*************************************************
 * Name:        decode_hb_z1
 *
 * Description: rANS decode polynomial vector HighBits(z1)
 *
 * Arguments:   - int32_t *hb_z1: pointer to polynomial vector HighBits(z1)
 *              - uint8_t *buf: pointer to output buffer
 **************************************************/
uint16_t decode_hb_z1(int32_t *hb_z1, const uint8_t *buf, uint16_t size_in) {
    size_t size_used;
    RansState rans;
    size_t size_hb_z1 = N * L;
    int32_t tmp;
    uint8_t s;
    const uint8_t *buf_start = buf;
    const uint8_t *buf_end = buf + size_in;

    if (RansDecInit(&rans, (uint8_t **) &buf)) {
        return 1; // corrupted initial state
    }

    for (size_t i = 0; i < size_hb_z1; i++) {
        s = symbol_hb_z1[RansDecGet(&rans, SCALE_BITS)];

        if (s >= M_HB_Z1) {
            return 1; // invalid symbol
        }

        if (s < OFFSET_HB_Z1_POS_START)
            tmp = s;  
        else
            tmp = s - OFFSET_HB_Z1_POS_START + OFFSET_HB_Z1_POS;

        hb_z1[i] = tmp;
        RansDecAdvanceSymbol(&rans, (uint8_t **) &buf, buf_end, &dsyms_hb_z1[s], SCALE_BITS);
    }

    if (RansDecVerify(&rans)) {
        return 1; // corrupted final state
    }

    size_used = buf - buf_start;
    if (size_used != size_in) {
        return 1; // size mismatch
    }

    return 0;
}